import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);
        GeometrySolver solver = new GeometrySolver();
        solver.solve(br, pw);
        pw.close();
    }
}

class GeometrySolver {
    final double DELTA = 1e-8;

    public void solve(BufferedReader br, PrintWriter pw) throws IOException {
        int n = Integer.parseInt(br.readLine());
        Circle[] circles = new Circle[n];
        for (int i = 0; i < n; i++) {
            String[] parts = br.readLine().split(" ");
            int x = Integer.parseInt(parts[0]);
            int y = Integer.parseInt(parts[1]);
            int r = Integer.parseInt(parts[2]);
            circles[i] = new Circle(new Point(x, y), r);
        }

        Set<Point> intersectionPoints = new TreeSet<>();
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                List<Point> pts = circleCircleIntersection(circles[i], circles[j]);
                if (pts != null) {
                    intersectionPoints.addAll(pts);
                }
            }
        }

        Map<Point, Integer> pointToId = new TreeMap<>();
        List<Set<Integer>> adjacencyList = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            List<Double> angles = new ArrayList<>();
            for (int j = 0; j < 100; j++) {
                angles.add(2 * Math.PI * j / 100);
            }
            for (Point p : intersectionPoints) {
                if (circles[i].contains(p)) {
                    double dx = p.x - circles[i].o.x;
                    double dy = p.y - circles[i].o.y;
                    double angle = Math.atan2(dy, dx);
                    if (angle < 0) angle += 2 * Math.PI;
                    angles.add(angle);
                }
            }
            Collections.sort(angles);
            Point direction = new Point(1, 0).scale(circles[i].r);
            Double[] sortedAngles = new TreeSet<>(angles).toArray(new Double[0]);
            for (Double a : sortedAngles) {
                Point p = circles[i].o.add(direction.rotate(a));
                ensurePointId(p, pointToId, adjacencyList);
            }
            for (int j = 0; j < sortedAngles.length; j++) {
                Point p1 = circles[i].o.add(direction.rotate(sortedAngles[j]));
                Point p2 = circles[i].o.add(direction.rotate(sortedAngles[(j + 1) % sortedAngles.length]));
                int u = pointToId.get(p1);
                int v = pointToId.get(p2);
                if (u != v) {
                    adjacencyList.get(u).add(v);
                    adjacencyList.get(v).add(u);
                }
            }
        }

        int totalVertices = adjacencyList.size();
        int totalEdges = 0;
        for (Set<Integer> neighbors : adjacencyList) {
            totalEdges += neighbors.size();
        }
        totalEdges /= 2;

        int connectedComponents = 0;
        boolean[] visited = new boolean[totalVertices];
        for (int i = 0; i < totalVertices; i++) {
            if (!visited[i]) {
                connectedComponents++;
                dfs(i, visited, adjacencyList);
            }
        }

        pw.println(1 + connectedComponents + totalEdges - totalVertices);
    }

    private void dfs(int u, boolean[] visited, List<Set<Integer>> adj) {
        visited[u] = true;
        for (int v : adj.get(u)) {
            if (!visited[v]) dfs(v, visited, adj);
        }
    }

    private void ensurePointId(Point p, Map<Point, Integer> map, List<Set<Integer>> adj) {
        if (!map.containsKey(p)) {
            int id = map.size();
            map.put(p, id);
            adj.add(new TreeSet<>());
        }
    }

    private List<Point> circleCircleIntersection(Circle c1, Circle c2) {
        double dx = c1.o.x - c2.o.x;
        double dy = c1.o.y - c2.o.y;
        double d = Math.hypot(dx, dy);
        double cosA = (c1.r * c1.r + d * d - c2.r * c2.r) / (2 * c1.r * d);
        if (cosA < -1 - DELTA || cosA > 1 + DELTA) return null;
        if (cosA < -1) cosA = -1;
        if (cosA > 1) cosA = 1;
        double alpha = Math.acos(cosA);
        Point dir = c2.o.sub(c1.o).norm();
        List<Point> res = new ArrayList<>();
        res.add(c1.o.add(dir.scale(c1.r).rotate(+alpha)));
        res.add(c1.o.add(dir.scale(c1.r).rotate(-alpha)));
        return res;
    }

    class Point implements Comparable<Point> {
        double x, y;
        Point(double x, double y) { this.x = x; this.y = y; }
        Point add(Point o) { return new Point(x + o.x, y + o.y); }
        Point sub(Point o) { return new Point(x - o.x, y - o.y); }
        Point rotate(double a) {
            double c = Math.cos(a), s = Math.sin(a);
            return new Point(x * c - y * s, x * s + y * c);
        }
        Point norm() {
            double len = length();
            if (len < DELTA) return new Point(0, 0);
            return scale(1.0 / len);
        }
        Point scale(double f) { return new Point(x * f, y * f); }
        double length() { return Math.hypot(x, y); }
        public String toString() { return String.format("%.6f %.6f", x, y); }
        public boolean equals(Object o) {
            if (!(o instanceof Point)) return false;
            Point p = (Point) o;
            return Math.abs(x - p.x) < DELTA && Math.abs(y - p.y) < DELTA;
        }
        public int compareTo(Point o) {
            if (Math.abs(x - o.x) > DELTA) return Double.compare(x, o.x);
            return Double.compare(y, o.y);
        }
    }

    class Circle {
        Point o;
        double r;
        Circle(Point o, double r) { this.o = o; this.r = r; }
        boolean contains(Point p) { return Math.abs(p.sub(o).length() - r) < DELTA; }
    }
}
