#include <bits/stdc++.h>
using namespace std;

class Point {
public:
    double x, y;
    Point(double x=0, double y=0): x(x), y(y) {}
    Point add(const Point& o) const { return Point(x + o.x, y + o.y); }
    Point sub(const Point& o) const { return Point(x - o.x, y - o.y); }
    Point rotate(double a) const {
        double c = cos(a), s = sin(a);
        return Point(x * c - y * s, x * s + y * c);
    }
    Point norm() const {
        double len = length();
        if (len < 1e-8) return Point(0, 0);
        return scale(1.0 / len);
    }
    Point scale(double f) const { return Point(x * f, y * f); }
    double length() const { return hypot(x, y); }
    string toString() const { char buf[64]; sprintf(buf, "%.6f %.6f", x, y); return string(buf); }
    bool equals(const Point& p) const {
        return fabs(x - p.x) < 1e-8 && fabs(y - p.y) < 1e-8;
    }
    int compareTo(const Point& o) const {
        if (fabs(x - o.x) > 1e-8) return (x < o.x) ? -1 : 1;
        if (fabs(y - o.y) > 1e-8) return (y < o.y) ? -1 : 1;
        return 0;
    }
    bool operator<(const Point& o) const {
        int cmpX = compareTo(o);
        if (cmpX != 0) return cmpX < 0;
        return compareTo(o) < 0;
    }
};

class Circle {
public:
    Point o;
    double r;
    Circle(Point o=Point(), double r=0): o(o), r(r) {}
    bool contains(const Point& p) const {
        return fabs(p.sub(o).length() - r) < 1e-8;
    }
};

vector<Point> circleCircleIntersection(const Circle& c1, const Circle& c2) {
    double dx = c1.o.x - c2.o.x;
    double dy = c1.o.y - c2.o.y;
    double d = hypot(dx, dy);
    double cosA = (c1.r * c1.r + d * d - c2.r * c2.r) / (2 * c1.r * d);
    if (cosA < -1 - 1e-8 || cosA > 1 + 1e-8) return {};
    if (cosA < -1) cosA = -1;
    if (cosA > 1) cosA = 1;
    double alpha = acos(cosA);
    Point dir = Point(dx, dy).norm();
    vector<Point> res;
    res.push_back(c1.o.add(dir.scale(c1.r).rotate(+alpha)));
    res.push_back(c1.o.add(dir.scale(c1.r).rotate(-alpha)));
    return res;
}

void dfs(int u, vector<bool>& visited, const vector<set<int>>& adj) {
    visited[u] = true;
    for (int v : adj[u]) {
        if (!visited[v]) dfs(v, visited, adj);
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n; cin >> n;
    vector<Circle> circles(n);
    for (int i = 0; i < n; i++) {
        int x, y, r; cin >> x >> y >> r;
        circles[i] = Circle(Point(x, y), r);
    }

    set<Point> intersectionPoints;
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            vector<Point> pts = circleCircleIntersection(circles[i], circles[j]);
            for (const auto& p : pts) {
                intersectionPoints.insert(p);
            }
        }
    }

    map<Point, int> pointToId;
    vector<set<int>> adjacencyList;
    auto ensurePointId = [&](const Point& p) {
        if (pointToId.count(p) == 0) {
            int id = (int)pointToId.size();
            pointToId[p] = id;
            adjacencyList.emplace_back();
        }
        return pointToId[p];
    };

    for (int i = 0; i < n; i++) {
        vector<double> angles;
        for (int j = 0; j < 100; j++) {
            angles.push_back(2 * M_PI * j / 100);
        }
        for (const auto& p : intersectionPoints) {
            if (circles[i].contains(p)) {
                double dx = p.x - circles[i].o.x;
                double dy = p.y - circles[i].o.y;
                double angle = atan2(dy, dx);
                if (angle < 0) angle += 2 * M_PI;
                angles.push_back(angle);
            }
        }
        sort(angles.begin(), angles.end());
        Point direction = Point(1, 0).scale(circles[i].r);
        vector<double> uniqueAngles;
        for (size_t j = 0; j < angles.size(); j++) {
            if (j == 0 || fabs(angles[j] - angles[j - 1]) > 1e-8) {
                uniqueAngles.push_back(angles[j]);
            }
        }
        vector<int> pointIds;
        for (double a : uniqueAngles) {
            Point p = circles[i].o.add(direction.rotate(a));
            int id = ensurePointId(p);
            pointIds.push_back(id);
        }
        int sz = (int)pointIds.size();
        for (int j = 0; j < sz; j++) {
            int u = pointIds[j];
            int v = pointIds[(j + 1) % sz];
            if (u != v) {
                adjacencyList[u].insert(v);
                adjacencyList[v].insert(u);
            }
        }
    }

    int totalVertices = (int)adjacencyList.size();
    int totalEdges = 0;
    for (const auto& neighbors : adjacencyList) {
        totalEdges += (int)neighbors.size();
    }
    totalEdges /= 2;

    int connectedComponents = 0;
