    for (int i = 0; i < totalVertices; i++) {
        if (!visited[i]) {
            connectedComponents++;
            dfs(i, visited, adjacencyList);
        }
    }

    cout << 1 + connectedComponents + totalEdges - totalVertices << "\n";

    return 0;
